# GDF cards: FOUNDATION of the Godot rebuild (docs/GODOT.md). Project skeleton, test harness, JSON + golden-fixture helpers,
# core ports (rng, clock, format, state, save), the Game/Data/Sfx autoloads, UiTokens, the API doc.
# Order: GDF01 -> GDF02 -> everything else (GDF15 CoreJson first among the rest, GDF04 golden helper before any golden test).
MODE = "godot"

PLAN = "docs/GODOT.md (the plan: layout, determinism and parity rules, card rules)"
HARNESS = ("godot/tests/harness.gd (GDF02): a test file starts with `extends \"res://tests/harness.gd\"` and every method named `test_*` is run; "
           "helpers `ok(cond, msg)`, `eq(a, b, msg)`, `near(a, b, eps, msg)`, `autoload(name) -> Node`")
GOLD = ("godot/tests/golden_util.gd (GDF04): `GoldenUtil.fixture(name) -> Variant` loads godot/tests/golden/<name>.json (whole JSON numbers come back as int, "
        "others float); `GoldenUtil.diff(a, b, eps = 1e-9) -> String` is \"\" when equal (numbers within eps) else a message naming the first difference; "
        "`GoldenUtil.same(a, b, eps = 1e-9) -> bool`")
JSCN = ("Golden fixtures are made by the JS reference: `sh tools/godot/golden.sh <name>` (GDF04) runs `tools/godot/golden_<name>.mjs` under macOS "
        "`jsc -m` and writes `godot/tests/golden/<name>.json`. Run it yourself and commit both files; the JSON is never hand-edited")
JSON_NOTE = ("GDScript's JSON parser returns EVERY number as float; `CoreJson` (GDF15) turns whole numbers back into int. "
             "GDScript `/` on two ints truncates: always convert with `float()` first when a JS division is meant")
NOTHING = "Everything not listed under files (other cards own it)."

CARDS = [

 dict(id="GDF01", title="Godot: project skeleton", needs=[],
  files=["godot/project.godot", "godot/.gitignore", "godot/autoload/game.gd", "godot/autoload/data.gd", "godot/autoload/sfx.gd",
         "godot/tests/runner.gd", "godot/core/.gitkeep", "godot/sim/.gitkeep", "godot/data/.gitkeep", "godot/scenes/.gitkeep",
         "godot/tv/.gitkeep", "godot/ui/.gitkeep", "godot/art/.gitkeep", "godot/tests/golden/.gitkeep"],
  goal="Create the empty Godot 4.7.2 project in `godot/`: 1280x720 base size, Compatibility renderer, three autoload stubs, the folder layout, and a placeholder test runner so `sh tools/godot/gtest.sh` already prints `GDTEST OK`.",
  read=[PLAN, "tools/godot/gtest.sh and tools/godot/_common.sh (how the project is shipped to CASE and run; `project.godot` must exist in godot/)"],
  steps=[
   "Write `godot/project.godot` as exactly these sections (Godot config format, one `key=value` per line, blank line between sections, first line `config_version=5`): `[application]` with `config/name=\"Webb, where's my car?\"` and `config/features=PackedStringArray(\"4.7\", \"GL Compatibility\")`; `[autoload]` with `Game=\"*res://autoload/game.gd\"`, `Data=\"*res://autoload/data.gd\"`, `Sfx=\"*res://autoload/sfx.gd\"`; `[display]` with `window/size/viewport_width=1280`, `window/size/viewport_height=720`, `window/stretch/mode=\"canvas_items\"`, `window/stretch/aspect=\"expand\"`, `window/handheld/orientation=0` (0 = landscape); `[rendering]` with `renderer/rendering_method=\"gl_compatibility\"`, `renderer/rendering_method.mobile=\"gl_compatibility\"`, `textures/canvas_textures/default_texture_filter=0` (Nearest, for the pixel look). No `run/main_scene` yet (GDF11 adds it).",
   "Write the three autoload stubs, each exactly two lines (use a TAB where indented): `godot/autoload/game.gd`: `extends Node` and `# Game singleton, filled in by GDF10.`; `godot/autoload/data.gd`: `extends Node` and `# Data singleton, filled in by GDF03.`; `godot/autoload/sfx.gd`: `extends Node` and `# Sfx singleton, filled in by GDF12.`",
   "Write `godot/.gitignore` with these lines: `.godot/`, `*.tmp`, `/export/`. Create the empty placeholder files `.gitkeep` listed under files (empty files, NOT `.gdignore`, which would hide the folder from Godot).",
   "Write the PLACEHOLDER `godot/tests/runner.gd` (GDF02 replaces it completely): `extends SceneTree`, then `func _initialize() -> void:` containing `print(\"GDTEST OK\")` and `quit(0)`.",
   "Run the acceptance commands below and paste their output."],
  accept=["`grep -c -E '^(Game|Data|Sfx)=\"\\*res://autoload/' godot/project.godot` prints `3`.",
          "`grep -E 'viewport_width=1280|viewport_height=720|stretch/mode=\"canvas_items\"|stretch/aspect=\"expand\"|gl_compatibility' godot/project.godot | wc -l` prints `6`.",
          "`test -f godot/autoload/game.gd && test -f godot/autoload/data.gd && test -f godot/autoload/sfx.gd && test -f godot/.gitignore && echo SKELETON OK` prints `SKELETON OK`.",
          "`sh tools/godot/gtest.sh | tail -1` prints `GDTEST OK` (the placeholder runner; the import step must not print parse errors for the autoload stubs)."],
  oos=["Any scene, theme, font or art. Real autoload code (GDF03, GDF10, GDF12). The real runner (GDF02)."]),

 dict(id="GDF02", title="Godot: test harness and runner", needs=["GDF01"],
  files=["godot/tests/harness.gd", "godot/tests/runner.gd", "godot/tests/test_harness.gd", "tools/godot/gtest.sh"],
  goal="The Godot test framework every later card uses: `harness.gd` (base class with assertions), `runner.gd` (finds and runs test files, prints failures, last line `GDTEST OK` or `GDTEST FAIL`, exit code 0 or 1) and a tiny passing `test_harness.gd`. Also make `gtest.sh` fail when Godot reports script errors.",
  read=[PLAN + " section 'Card rules for Godot cards'", "tools/godot/gtest.sh and tools/godot/_common.sh", "tests/harness.js (the JS harness this mirrors: ok, eq, near, done)"],
  steps=[
   "`godot/tests/harness.gd`: `extends RefCounted`, no `class_name`. Public vars: `var failures: Array[String] = []`, `var checks: int = 0`, `var current_test: String = \"\"`. Methods (all typed): `func before_each() -> void: pass` (tests may override); `func ok(cond: bool, msg: String = \"\") -> void` (checks += 1; when false append `current_test + \": \" + msg` to failures); `func eq(a: Variant, b: Variant, msg: String = \"\") -> void` (checks += 1; two Arrays or Dictionaries are equal when `JSON.stringify(a, \"\", true) == JSON.stringify(b, \"\", true)`; everything else uses `a == b`; on mismatch append `current_test: msg: expected <b> got <a>` using `str()` of both); `func near(a: float, b: float, eps: float = 1e-9, msg: String = \"\") -> void` (fail when `absf(a - b) > eps`, message includes both numbers); `func fail(msg: String) -> void` (always a failure); `func autoload(autoload_name: String) -> Node`: return `Engine.get_main_loop().root.get_node_or_null(autoload_name)` if it is not null, otherwise `load(\"res://autoload/\" + autoload_name.to_lower() + \".gd\").new()` (a fresh instance not added to the tree); `func tree() -> SceneTree: return Engine.get_main_loop() as SceneTree`.",
   "`godot/tests/runner.gd`: `extends SceneTree`; all work happens in `func _initialize() -> void`. (1) `var args := OS.get_cmdline_user_args()` (the words after `--`). (2) Stems: if args is empty, list `res://tests` with `DirAccess.get_files_at(\"res://tests\")` and keep names that start with `test_` and end with `.gd`, sorted; otherwise each arg is a stem, with `test_` prepended when it does not already start with `test_` and `.gd` appended. (3) For every file: `var sc = load(\"res://tests/\" + file)`; if it is null or `sc.can_instantiate()` is false print `FAIL <file>: could not load or parse` and count a failure. Else `var t = sc.new()`, collect the methods with `t.get_method_list()` whose `name` begins with `test_`, sort by name, and for each: `t.current_test = name; t.before_each(); t.call(name)`; a test that ran but made no new checks (`t.checks` unchanged) is a failure `<name>: made no checks`. (4) After a file print `PASS <file> (<n> checks)` or `FAIL <file>` followed by one line per failure indented two spaces. (5) At the end print `GDTEST OK` and `quit(0)` when there were no failures and at least one test ran, otherwise print `GDTEST FAIL` and `quit(1)` (zero tests run is a failure). `GDTEST OK` / `GDTEST FAIL` must be the LAST printed line.",
   "`godot/tests/test_harness.gd`: `extends \"res://tests/harness.gd\"`. `test_ok_and_eq`: ok(true), eq(1, 1), eq([1, 2], [1, 2]), eq({\"a\": 1}, {\"a\": 1}), eq(\"x\", \"x\"). `test_near`: near(0.1 + 0.2, 0.3, 1e-9). `test_failure_is_recorded`: `var before := failures.size()`, call `ok(false, \"x\")`, then `var grew: bool = failures.size() == before + 1`, `failures.pop_back()`, `checks` stays, then `ok(grew, \"a failing ok() adds one failure\")`; do the same for `eq(1, 2, \"y\")` and `near(1.0, 2.0, 1e-9, \"z\")`. `test_autoload_helper`: `ok(autoload(\"Game\") != null, \"Game stub reachable\")`, `ok(tree() != null, \"tree\")`.",
   "Edit `tools/godot/gtest.sh` so script errors cannot slip through (Godot keeps running after a runtime error inside a test): capture the ssh output in a variable (`OUT=$(ssh ... 2>&1); RC=$?`, keep the existing ssh command and the `grep -v` filter on the printed text), print it, then `if printf '%s\\n' \"$OUT\" | grep -q -E 'SCRIPT ERROR|Parse Error'; then echo 'GDTEST FAIL (script errors above)'; exit 1; fi; exit $RC`. `gshot.sh` is not touched.",
   "Make the negative check yourself (it is in the acceptance list) and delete the temporary failing test file afterwards."],
  accept=["`sh tools/godot/gtest.sh test_harness | tail -3` shows a `PASS test_harness.gd` line and ends with `GDTEST OK`.",
          "`printf 'extends \"res://tests/harness.gd\"\\nfunc test_bad():\\n\\tok(false, \"boom\")\\n' > godot/tests/test_zz_fail.gd; sh tools/godot/gtest.sh zz_fail > /tmp/gdf02.txt; echo \"exit=$?\"; tail -1 /tmp/gdf02.txt; rm godot/tests/test_zz_fail.gd` prints `exit=1` and `GDTEST FAIL`.",
          "`printf 'extends \"res://tests/harness.gd\"\\nfunc test_err():\\n\\tvar n = null\\n\\tn.foo()\\n\\tok(true, \"after\")\\n' > godot/tests/test_zz_err.gd; sh tools/godot/gtest.sh zz_err > /tmp/gdf02.txt; echo \"exit=$?\"; tail -1 /tmp/gdf02.txt; rm godot/tests/test_zz_err.gd` prints `exit=1` and a last line starting `GDTEST FAIL`."],
  oos=["Tests for game code. Scene tests (GDF11 shows how). gshot.sh."]),

 dict(id="GDF15", title="Godot: CoreJson (int-preserving JSON)", needs=["GDF01", "GDF02"],
  files=["godot/core/json.gd", "godot/tests/test_json.gd"],
  goal="`CoreJson`: the one way the game reads and writes JSON. " + JSON_NOTE + ".",
  read=[PLAN, HARNESS, "src/save/save.js (the JSON the save format needs)"],
  steps=[
   "`godot/core/json.gd`: `class_name CoreJson`, `extends RefCounted`. All functions `static`, typed.",
   "`static func normalize(v: Variant) -> Variant`: returns a deep copy where every float `f` with `f == floor(f)` and `absf(f) < 9.0e15` becomes `int(f)`; Arrays and Dictionaries are copied recursively (dictionary keys are left as they are); everything else (String, bool, null, other floats) is returned as is.",
   "`static func try_parse(text: String) -> Dictionary`: `var j := JSON.new()`; `var err := j.parse(text)`; return `{\"ok\": false, \"value\": null}` when `err != OK`, else `{\"ok\": true, \"value\": normalize(j.data)}`.",
   "`static func parse(text: String) -> Variant`: `try_parse(text).value` (null on any parse error, and also for the text `null`).",
   "`static func load_file(path: String) -> Variant`: `FileAccess.open(path, FileAccess.READ)`; null when it cannot be opened, else `parse(f.get_as_text())`.",
   "`static func stringify(v: Variant) -> String`: `JSON.stringify(v, \"\", true)` (compact, keys sorted so output is deterministic).",
   "`static func save_file(path: String, v: Variant) -> bool`: open with `FileAccess.WRITE`, return false when null, else `store_string(stringify(v))` and return true.",
   "`godot/tests/test_json.gd` with these tests: `test_normalize` (`normalize(1.0)` is int: check `typeof(normalize(1.0)) == TYPE_INT`; `normalize(2.5)` stays float 2.5; `normalize({\"a\": [1.0, 2.5, {\"b\": 3.0}]})` has `a[0]` int 1, `a[1]` float 2.5, `a[2].b` int 3; strings, `true` and null unchanged; `normalize(1.0e16)` stays float); `test_parse` (`parse('{\"x\":5,\"y\":[1,2.5]}')` gives x int 5, y[0] int 1, y[1] 2.5; `parse('nope')` is null; `try_parse('nope').ok` is false; `try_parse('null').ok` is true and its value null); `test_stringify_sorted` (`stringify({\"b\": 1, \"a\": 2})` equals `{\"a\":2,\"b\":1}`); `test_file_roundtrip` (`save_file(\"user://gdf15_tmp.json\", {\"n\": 7, \"s\": \"hi\"})` is true, `load_file` gives n int 7 and s hi, then `DirAccess.remove_absolute(ProjectSettings.globalize_path(\"user://gdf15_tmp.json\"))`; `load_file(\"user://does_not_exist.json\")` is null)."],
  accept=["`sh tools/godot/gtest.sh test_json | tail -1` prints `GDTEST OK`."],
  oos=[NOTHING]),

 dict(id="GDF03", title="Godot: data export tool and Data autoload", needs=["GDF01", "GDF02", "GDF15"],
  files=["tools/godot/export_data.mjs", "tools/godot/export_data.sh", "godot/autoload/data.gd", "godot/data/adverts.json", "godot/data/archetypes.json",
         "godot/data/cars.json", "godot/data/chatter.json", "godot/data/faults.json", "godot/data/headlines.json", "godot/data/jobtypes.json",
         "godot/data/names.json", "godot/data/owners.json", "godot/data/paint.json", "godot/tests/golden/data_counts.json", "godot/tests/test_data.gd"],
  goal="Export every `src/data/*.js` table to JSON under `godot/data/` with a script (never by hand), and the `Data` autoload that serves them: one accessor per JS data module.",
  read=[PLAN, "src/data/*.js (the export lists: adverts.js, cars.js, chatter.js, faults.js, headlines.js, jobtypes.js, names.js, owners.js, paint.js)", "tools/art/export_profiles.mjs (the existing jsc export style)", "godot/core/json.gd (GDF15)", HARNESS, JSON_NOTE],
  steps=[
   "`tools/godot/export_data.mjs` (run as `jsc -m tools/godot/export_data.mjs` from the repo root; jsc has no console: use `print`). Import (paths relative to the file: `../../src/data/...`): `ADVERTS` from adverts.js; `CARS`, `ARCHETYPES` from cars.js; `CHATTER` from chatter.js; `FAULTS`, `TIER_MULT` from faults.js; `GENERIC`, `CARWORLD`, `REACTIVE` from headlines.js; `JOB_TYPES` from jobtypes.js; `FIRST`, `LAST`, `PREFIX` from names.js; `OWNERS` from owners.js; `PAINT` from paint.js. Build `OUT` = an ordered list of `[stem, value]`: `adverts`=ADVERTS, `archetypes`=ARCHETYPES, `cars`=CARS, `chatter`=CHATTER, `faults`=`{faults: FAULTS, tier_mult: TIER_MULT}`, `headlines`=`{generic: GENERIC, carworld: CARWORLD, reactive: REACTIVE}`, `jobtypes`=JOB_TYPES, `names`=`{first: FIRST, last: LAST, prefix: PREFIX}`, `owners`=OWNERS, `paint`=PAINT. For each pair print TWO lines: `@@<stem>` then `JSON.stringify(value)`. Last, print `@@_counts` and the JSON of an object with these keys (a count is `.length` for an array and `Object.keys(x).length` for an object): `adverts`, `archetypes`, `cars`, `chatter`, `faults` (FAULTS), `faults_tier_mult`, `headlines_generic`, `headlines_carworld`, `headlines_reactive`, `jobtypes`, `names_first`, `names_last`, `names_prefix`, `owners`, `paint`.",
   "`tools/godot/export_data.sh` (POSIX sh, `set -eu`, `cd` to the repo root from `$(dirname \"$0\")/../..`; `JSC` defaults to `/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc`): `mkdir -p godot/data godot/tests/golden`; run the mjs into a `mktemp` file; then `python3 -I - \"$TMP\" <<'PY'` (a heredoc script that reads the file, walks the lines in pairs `@@name` / json, parses each JSON with `json.loads` and writes it with `json.dump(v, f, ensure_ascii=True, separators=(',', ':'))` to `godot/data/<name>.json`, except `_counts` which goes to `godot/tests/golden/data_counts.json`) and finally prints `EXPORTED <n> files` (n counts all files written, 11 expected). Delete the temp file. Run it and commit the generated JSON.",
   "`godot/autoload/data.gd` (replace the stub): `extends Node`. `var _cache: Dictionary = {}`. `func _table(stem: String) -> Variant`: if not cached, `_cache[stem] = CoreJson.load_file(\"res://data/\" + stem + \".json\")`; return it. One accessor per module, each `return _table(\"<stem>\")` with a typed return: `func adverts() -> Array`, `func archetypes() -> Array`, `func cars() -> Array`, `func chatter() -> Dictionary`, `func faults() -> Array` (the `faults` list inside faults.json), `func faults_tier_mult() -> Dictionary` (keys are the STRINGS \"1\", \"2\", \"3\"), `func headlines() -> Dictionary` (keys generic, carworld, reactive), `func jobtypes() -> Array`, `func jobs() -> Array` (alias of jobtypes, the name the shared contract uses), `func names() -> Dictionary` (keys first, last, prefix), `func owners() -> Array`, `func paint() -> Dictionary`. Lookup helpers (return `{}` / `\"\"` when unknown, never an error): `func car_by_id(id: String) -> Dictionary`, `func job_type_by_id(id: String) -> Dictionary`, `func advert_by_id(id: String) -> Dictionary`, `func fault_by_id(id: String) -> Dictionary`, `func paint_of(id: String) -> String` (`\"#888888\"` for an unknown id, like the JS). Build each lookup by a linear scan; no caching needed. JS data-module FUNCTIONS (chatterFor, ownerName, customerName, fillText...) are NOT ported here; sim cards do that.",
   "`godot/tests/test_data.gd`: `var d := autoload(\"Data\")`. `test_counts_match_js`: `var c = CoreJson.load_file(\"res://tests/golden/data_counts.json\")` and check `d.adverts().size() == c.adverts`, `archetypes`, `cars`, `chatter().size()`, `faults()`, `faults_tier_mult()`, `headlines().generic.size()` == `headlines_generic`, `.carworld`, `.reactive.size()`, `jobtypes()`, `jobs().size() == jobtypes().size()`, `names().first/last/prefix`, `owners()`, `paint().size()`. `test_spot_values`: `d.cars()[0].id == \"t1_allergy\"` and `d.cars()[0].basePrice == 3500` and `typeof(d.cars()[0].basePrice) == TYPE_INT`; `d.car_by_id(\"t3_aston\").tier == 3`; `d.car_by_id(\"nope\") == {}`; `d.paint()[\"t1_robbin\"] == \"#C9A227\"`; `d.paint_of(\"nope\") == \"#888888\"`; `d.faults_tier_mult()[\"2\"]` near 1.8; `d.fault_by_id(\"puncture\").severity == \"minor\"`; `d.advert_by_id(\"paper\").name == \"Parish Pump Gazette\"`; `d.owners()[0]` is a String; `d.archetypes()[0] == \"micro\"`. `test_cars_unique_ids`: every id in `d.cars()` is unique and every car has keys `id, name, year, archetype, tier, basePrice`."],
  accept=["`sh tools/godot/export_data.sh` prints `EXPORTED 11 files`, and running it a second time leaves `git status --short godot/data godot/tests/golden/data_counts.json` showing no further changes.",
          "`python3 -c \"import json;c=json.load(open('godot/tests/golden/data_counts.json'));print(c['cars'],c['jobtypes'],c['paint'])\"` prints three numbers (31 16 31 at the time of writing).",
          "`sh tools/godot/gtest.sh test_data | tail -1` prints `GDTEST OK`."],
  oos=["Porting the JS functions that live in data modules. Hand-editing JSON. The `src/data` JS."]),

 dict(id="GDF04", title="Godot: golden fixture helper", needs=["GDF01", "GDF02", "GDF15"],
  files=["tools/godot/golden_common.mjs", "tools/godot/golden.sh", "tools/godot/golden_example.mjs", "godot/tests/golden/example.json",
         "godot/tests/golden_util.gd", "godot/tests/test_golden_util.gd"],
  goal="The pattern every port card follows to compare against the JS reference: a jsc script prints JSON, `golden.sh` stores it as a fixture, `GoldenUtil` compares in a Godot test. This card builds the pattern and one documented example.",
  read=[PLAN + " section 'Determinism and parity'", "godot/core/json.gd (GDF15)", HARNESS, "tools/art/export_profiles.mjs (jsc -m script style)"],
  steps=[
   "`tools/godot/golden_common.mjs`: header comment explaining the pattern in 6 lines max. Exports `SEEDS = [0, 1, 42, 12345, 987654321, 4294967295]` and `emit(obj)` which calls `print(JSON.stringify(obj))` exactly once (a fixture is ONE line of JSON). No other exports.",
   "`tools/godot/golden_example.mjs`: `import { emit } from './golden_common.mjs';` then `emit({ numbers: [1, 2.5, 0.1 + 0.2, -3], text: 'ok', nested: { list: [true, null, 'x'], empty: {} } });`.",
   "`tools/godot/golden.sh <name>` (POSIX sh, `set -eu`, `cd` to the repo root from `$(dirname \"$0\")/../..`, usage line and exit 2 without an argument; `JSC` defaults to `/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc`): require `tools/godot/golden_<name>.mjs` to exist (else print `no golden_<name>.mjs` and exit 1); run `\"$JSC\" -m tools/godot/golden_<name>.mjs` into a `mktemp` file; pipe that file through `python3 -I -c 'import json,sys; print(json.dumps(json.loads(sys.stdin.buffer.read().decode(\"utf-8\")), ensure_ascii=True, separators=(\",\", \":\")))'` into `godot/tests/golden/<name>.json` (this validates the JSON and makes the fixture pure ASCII); print `wrote godot/tests/golden/<name>.json (<bytes> bytes)`. Exit non-zero if jsc or python fails (nothing half-written: write to a temp file, `mv` at the end).",
   "`godot/tests/golden_util.gd`: `class_name GoldenUtil`, `extends RefCounted`, all static. `static func fixture(name: String) -> Variant`: `CoreJson.load_file(\"res://tests/golden/\" + name + \".json\")`. `static func diff(a: Variant, b: Variant, eps: float = 1e-9, path: String = \"$\") -> String`: returns \"\" when equal, else a one-line message starting with the path of the FIRST difference (e.g. `$.cars[3].tier: expected 2 got 3`). Rules: both int or float -> equal when both are int and `a == b`, otherwise when `absf(float(a) - float(b)) <= eps`; both Dictionary -> same set of keys compared as `str(key)` (report `missing key` / `extra key` with the key), then recurse in the key order of `a` using `path + \".\" + key`; both Array -> same size (report both sizes) then recurse with `path + \"[i]\"`; both String, both bool, both null -> `==`; any other pairing -> `type mismatch` message with both `typeof` numbers. `static func same(a: Variant, b: Variant, eps: float = 1e-9) -> bool: return diff(a, b, eps) == \"\"`.",
   "`godot/tests/test_golden_util.gd`: `test_diff_rules` (equal ints; int 1 vs float 1.0 equal; 0.30000000000000004 vs 0.3 equal; 0.31 vs 0.3 differs; nested dict/array equal; missing key reported; array size mismatch reported; message for `{\"a\": [1, 2]}` vs `{\"a\": [1, 3]}` starts with `$.a[1]`; string vs int is a type mismatch; null equals null). `test_example_fixture`: `GoldenUtil.same(GoldenUtil.fixture(\"example\"), {\"numbers\": [1, 2.5, 0.30000000000000004, -3], \"text\": \"ok\", \"nested\": {\"list\": [true, null, \"x\"], \"empty\": {}}})` is true.",
   "Run `sh tools/godot/golden.sh example` and commit the produced `godot/tests/golden/example.json`."],
  accept=["`sh tools/godot/golden.sh example` prints `wrote godot/tests/golden/example.json` and `cat godot/tests/golden/example.json` is one line starting `{\"numbers\":[1,2.5,`.",
          "`sh tools/godot/golden.sh nosuchname; echo exit=$?` prints `no golden_nosuchname.mjs` and `exit=1`.",
          "`sh tools/godot/gtest.sh test_golden_util | tail -1` prints `GDTEST OK`."],
  oos=[NOTHING]),

 dict(id="GDF05", title="Godot: CoreRng (port of core/rng.js)", needs=["GDF04"],
  files=["godot/core/rng.gd", "tools/godot/golden_rng.mjs", "godot/tests/golden/rng.json", "godot/tests/test_rng.gd"],
  goal="Exact port of `src/core/rng.js`: the same seeds give the same numbers as the JS build (bit for bit; floats equal).",
  read=["src/core/rng.js (read it all)", "tests/rng.test.mjs (reference values)", HARNESS, GOLD, JSCN, JSON_NOTE],
  steps=[
   "`godot/core/rng.gd`: `class_name CoreRng`, `extends RefCounted`, all functions `static`, typed. The random state is `state.rng` (an int holding a uint32) inside the state Dictionary. 64-bit GDScript ints make this easy; mask EVERY result with `& 0xFFFFFFFF`.",
   "`static func _imul(a: int, b: int) -> int: return (a * b) & 0xFFFFFFFF`.",
   "`static func _step(state: Dictionary) -> int` (indent the body with tabs): `state.rng = (int(state.rng) + 0x6D2B79F5) & 0xFFFFFFFF`; `var t: int = state.rng`; `t = _imul(t ^ (t >> 15), t | 1)`; `t = (t ^ ((t + _imul(t ^ (t >> 7), t | 61)) & 0xFFFFFFFF)) & 0xFFFFFFFF`; `return (t ^ (t >> 14)) & 0xFFFFFFFF`. Do not 'simplify' it.",
   "Public API (names are the JS names in snake_case): `seed_rng(state: Dictionary, seed_value: int) -> void` (`state.rng = seed_value & 0xFFFFFFFF`, so -1 becomes 4294967295); `rand(state) -> float` (`float(_step(state)) / 4294967296.0`); `rand_int(state, lo: int, hi: int) -> int` (`lo + int(floor(rand(state) * float(hi - lo + 1)))`); `chance(state, p: float) -> bool` (`rand(state) < p`); `pick(state, arr: Array) -> Variant` (`arr[rand_int(state, 0, arr.size() - 1)]`; an empty array returns null WITHOUT drawing); `weighted(state, items: Array) -> Variant`: items are Dictionaries with a numeric `w`; `total` as a FLOAT sum of `w`; if `total <= 0` return `{}` without drawing; draw ONE `r = rand(state)`; loop `r -= float(items[i].w) / total; if r < 0.0: return items[i]`; if the loop ends, return the last item whose `w > 0`; `round_to(x: float, step_size: float) -> float` (`snappedf(floor(x / step_size + 0.5) * step_size, 0.000001)`: JS `Math.round` rounds halves UP, so do not use `roundf`/`round`); `clamp_value(x: float, lo: float, hi: float) -> float` (`minf(hi, maxf(lo, x))`).",
   "`tools/godot/golden_rng.mjs` (imports `emit, SEEDS` from `./golden_common.mjs` and the JS functions from `../../src/core/rng.js`): constants `POOL = ['a','b','c','d']`, `WEIGHTS = [{w:1,id:'x'},{w:3,id:'y'},{w:0,id:'z'},{w:6,id:'w'}]`. The op list `OPS` (in this order): `rand` x5, `randInt [1,6]` x5, `randInt [-3,3]` x5, `randInt [7,7]` x2, `chance [0.3]` x5, `pick` x5 (draws from POOL), `weighted` x8 (draws from WEIGHTS, the output is the picked `.id`), `roundTo [0.5]` x3, `roundTo [0.01]` x3 (each `roundTo` op draws one `rand` and rounds `rand * 100`). For every seed in SEEDS, create `{rng: 0}`, `seedRng(s, seed)`, run all ops in order, and record `out` (list of results). Also record `final: s.rng`. Emit `{ ops: OPS, cases: [{seed, out, final}, ...], statics: [...] }` where `statics` has entries `{fn, args, out}` for: `roundTo [1.2345, 0.01]`, `[2.5, 1]`, `[-2.5, 1]`, `[0.125, 0.25]`, `[7, 5]`; `clamp [5,0,3]`, `[-1,0,3]`, `[2,0,3]`; and `seedRng`-then-read cases `{fn:'seed', args:[-1], out: <state.rng after seedRng(s, -1)>}`, `[3.7]`, `[4294967296]`.",
   "`godot/tests/test_rng.gd`: `test_golden_sequences`: load `GoldenUtil.fixture(\"rng\")`; for each case seed a Dictionary `{\"rng\": 0}` with `CoreRng.seed_rng`, replay `ops` in the same order (match on op name; `pick` uses POOL, `weighted` uses WEIGHTS and takes `.id`, `roundTo` draws `rand` then `round_to(r * 100.0, step)`; ops with `args` pass them), compare every output with `GoldenUtil.diff` (eps 1e-12) and finally `state.rng == case.final`. `test_statics` replays `statics` (`seed` entries use `seed_rng(s, int(args[0]))` and read `s.rng`; note `3.7` becomes `int(3.7)` = 3 in GDScript and `>>> 0` of 3.7 is also 3). `test_known_values`: seed 12345 gives `rand` values near 0.9797282677609473, 0.3067522644996643, 0.484205421525985 (eps 1e-12); seed 1 first raw draw: `rand * 4294967296.0` rounds to 2693262067 and the second to 11749833. `test_edge_cases`: `pick` of `[]` is null and leaves `state.rng` unchanged; `weighted` of `[{\"w\": 0}]` is `{}`; `weighted` with only the last item weighted always returns it; same seed twice gives identical 20 numbers; different seeds differ; `rand` is always in [0, 1)."],
  accept=["`sh tools/godot/golden.sh rng` prints `wrote godot/tests/golden/rng.json`.",
          "`sh tools/godot/gtest.sh test_rng | tail -1` prints `GDTEST OK`."],
  oos=["`weighted` for non-Dictionary items. Any use of GDScript randf/randi. Game code that calls the rng (sim cards)."]),

 dict(id="GDF06", title="Godot: CoreClock (port of core/clock.js)", needs=["GDF04"],
  files=["godot/core/clock.gd", "tools/godot/golden_clock.mjs", "godot/tests/golden/clock.json", "godot/tests/test_clock.gd"],
  goal="Exact port of `src/core/clock.js`, the 365-day calendar.",
  read=["src/core/clock.js (read it all)", "tests/clock.test.mjs", HARNESS, GOLD, JSCN],
  steps=[
   "`godot/core/clock.gd`: `class_name CoreClock`, `extends RefCounted`, static, typed. Constants: `const MONTH_NAMES: Array[String] = [\"January\", ... \"December\"]` (12), `const MONTH_LENGTHS: Array[int] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]`, `const DAYS_IN_YEAR := 365`, `const AUCTION_DAY_OF_MONTH := 24`. A starts table `static func _month_start(m: int) -> int` (1-based day number of the 1st of month `m`: sum of the previous lengths plus 1).",
   "Where the JS throws a RangeError the GDScript version returns a sentinel and never errors: `static func valid_day(day: Variant) -> bool` (int or float, whole, 1..365). `static func date_of(day) -> Dictionary` returns `{\"month\": m, \"dayOfMonth\": d, \"monthName\": name}` (keys exactly like the JS) or `{}` when the day is invalid. `static func day_of_year_start(month: int) -> int` (-1 when month is not 1..12). `static func is_month_start(day) -> bool` (false when invalid). `static func is_auction_day(day) -> bool` (false when invalid). `static func days_left_in_month(day) -> int` (`MONTH_LENGTHS[month - 1] - dayOfMonth`; -1 when invalid).",
   "`tools/godot/golden_clock.mjs`: emit `{ dates: [[day, month, dayOfMonth, monthName] for day 1..365], monthStarts: [dayOfYearStart(m) for m 1..12], monthStartDays: [days 1..365 where isMonthStart], auctionDays: [days where isAuctionDay], daysLeft: [daysLeftInMonth(day) for day 1..365], constants: {names: MONTH_NAMES, lengths: MONTH_LENGTHS, year: DAYS_IN_YEAR, auction: AUCTION_DAY_OF_MONTH} }` (import everything from `../../src/core/clock.js`).",
   "`godot/tests/test_clock.gd`: `test_dates_all_365` (every row of `dates` matches `date_of`), `test_month_starts`, `test_month_start_days`, `test_auction_days` (collect the days where `is_auction_day` is true and compare to `auctionDays`; 12 days), `test_days_left`, `test_constants` (names, lengths, year, auction vs the fixture; lengths sum to 365), `test_out_of_range` (`date_of(0)`, `date_of(366)`, `date_of(1.5)` are `{}`; `valid_day(365)` true; `day_of_year_start(0)` and `(13)` are -1; `is_month_start(0)` false; `days_left_in_month(400)` is -1)."],
  accept=["`sh tools/godot/golden.sh clock` prints `wrote godot/tests/golden/clock.json`.",
          "`sh tools/godot/gtest.sh test_clock | tail -1` prints `GDTEST OK`."],
  oos=[NOTHING]),

 dict(id="GDF07", title="Godot: CoreFormat (port of core/format.js)", needs=["GDF04"],
  files=["godot/core/format.gd", "tools/godot/golden_format.mjs", "godot/tests/golden/format.json", "godot/tests/test_format.gd"],
  goal="Exact port of `src/core/format.js`: money, one decimal, dates, stars, plurals. Source files stay ASCII: the pound sign is built with `char(163)`, the stars with `char(9733)` and `char(9734)`.",
  read=["src/core/format.js (read it all)", "tests/format.test.mjs", HARNESS, GOLD, JSCN],
  steps=[
   "`godot/core/format.gd`: `class_name CoreFormat`, `extends RefCounted`, static, typed. `static func pound() -> String: return char(163)`. `static func _comma_group(digits: String) -> String`: insert a comma before every group of three digits counted from the right (`\"1234567\"` -> `\"1,234,567\"`, `\"999\"` unchanged).",
   "`static func money(n: float) -> String`: `var rounded: int = int(floor(n + 0.5))` (JS `Math.round`: halves go UP, so 12.5 -> 13 and -12.5 -> -12); `sign = \"-\"` when `rounded < 0` else empty; return `sign + pound() + _comma_group(str(absi(rounded)))`. A value that rounds to 0 prints `\"\" + pound + \"0\"` (never a minus sign).",
   "`static func one_dp(n: float) -> String`: `var s := \"%.1f\" % (n + 1e-9)`; if `s == \"-0.0\"` return `\"0.0\"`; return s.",
   "`static func date_text(day: int) -> String`: `\"24 February\"` style (day number, a space, the month name; February has 28 days; do NOT depend on CoreClock: copy the two small arrays privately as `_MONTH_NAMES` and `_MONTH_LENGTHS`). Returns `\"\"` for a day outside 1..365.",
   "`static func stars(n: float) -> String`: `v = clampi(int(floor(n + 0.5)), 0, 10)`; return `char(9733)` repeated `v` times followed by `char(9734)` repeated `10 - v` times (use `.repeat()` on the one-character strings).",
   "`static func plural(n: int, one: String, many: String) -> String`: `str(n) + \" \" + (one if n == 1 else many)`.",
   "`tools/godot/golden_format.mjs`: emit `{ money: [[n, money(n)]...], oneDp: [[n, oneDp(n)]...], dateText: [dateText(d) for d 1..365], stars: [[n, stars(n)]...], plural: [[n, one, many, plural(n, one, many)]...] }` with these inputs. money: 1234, 0, 1234567, 12.6, -1234, -0.4, 999, 1000, 12.4, -12.6, 0.4, 1000000000, 0.5, -0.5, 12.5, -12.5, -0.6, 100, 99999.5, 1000000000000. oneDp: 2, 7.46, 0, 7.44, 10, -1.25, 0.05, 0.25, 2.675, -0.04, 99.95. stars: 0, 3.4, 3.5, 7, 10, 11, -2, 4.5. plural: [1,'car','cars'], [0,'car','cars'], [2,'day','days'], [-1,'bill','bills'], [101,'win','wins'].",
   "`godot/tests/test_format.gd`: `test_money` (each pair), `test_one_dp`, `test_date_text` (all 365; also `date_text(0)` and `(366)` are `\"\"`), `test_stars` (each pair; also check `stars(3).length() == 10`), `test_plural`, `test_ascii_source`: read `res://core/format.gd` with `FileAccess.get_file_as_string` and check no character has code > 127 (loop over `get_string_from_utf8`/`to_utf8_buffer()` bytes: no byte >= 128), `test_pound_is_one_char`: `CoreFormat.pound().length() == 1` and `unicode_at(0) == 163`."],
  accept=["`sh tools/godot/golden.sh format` prints `wrote godot/tests/golden/format.json`.",
          "`grep -nP '[^\\x00-\\x7F]' godot/core/format.gd` prints nothing.",
          "`sh tools/godot/gtest.sh test_format | tail -1` prints `GDTEST OK`."],
  oos=["Fonts (whether the pixel font has the star glyphs is a UI card's problem)."]),

 dict(id="GDF08", title="Godot: CoreState (port of core/state.js)", needs=["GDF04", "GDF05"],
  files=["godot/core/state.gd", "tools/godot/golden_state.mjs", "godot/tests/golden/state.json", "godot/tests/test_state.gd"],
  goal="Exact port of `src/core/state.js`: `CoreState.new_game_state(seed)` returns a fresh Dictionary with EXACTLY the JS keys (camelCase key names are kept: `garageSlots`, `nextId`, `priceMult`, `refreshedDay`, `lastResults`, `jobsDone`, ... because saves, fixtures and sim ports all use them).",
  read=["src/core/state.js (read it all)", "tests/state.test.mjs", "godot/core/rng.gd (GDF05)", HARNESS, GOLD, JSCN],
  steps=[
   "`godot/core/state.gd`: `class_name CoreState`, `extends RefCounted`. `const PLATE_KEYS: Array[String] = [\"fatcat\", \"stable\", \"household\", \"hammer\"]`. `static func new_game_state(seed_value: int = 1) -> Dictionary`: builds the Dictionary literal with the same keys, same order and same initial values as the JS (`v: 1, seed: seed, rng: 0, day: 1, cash: 20000, reputation: 40, buzz: 0, garageSlots: 3, nextId: 1, market: {priceMult: 1}, cars: [], shop: {listings: [], refreshedDay: 1}, requests: [], auction: {month: 1, lots: [], consigned: [], lastResults: []}, stats: {...7 keys...}, plates: {all four false}, headlines: [], pending: [], sit: [], today: {day: 1, headline: \"\", events: [], monthReport: null}, lastMonthReport: null, flags: {gameOver: false, won: false, reason: \"\"}, log: []`), then `CoreRng.seed_rng(state, seed_value)` and returns it. Every call builds NEW containers (never share a constant Dictionary or Array between calls). Whole numbers are GDScript ints (`priceMult: 1`).",
   "`tools/godot/golden_state.mjs`: emit `{ plateKeys: PLATE_KEYS, states: [{seed: s, state: newGameState(s)} for s in [1, 0, 42, 4294967295]], defaultSeed: newGameState() }`.",
   "`godot/tests/test_state.gd`: `test_matches_js` (for each fixture entry `GoldenUtil.diff(CoreState.new_game_state(seed), entry.state)` is \"\"; also `new_game_state()` vs `defaultSeed`), `test_plate_keys`, `test_fresh_containers` (mutating `cars` and `plates` of one state does not change the next state), `test_json_roundtrip` (`CoreJson.parse(CoreJson.stringify(state))` is `GoldenUtil.same` to the state), `test_rng_seeded` (state.rng for seed 42 equals 42; for seed 4294967295 equals 4294967295)."],
  accept=["`sh tools/godot/golden.sh state` prints `wrote godot/tests/golden/state.json`.",
          "`sh tools/godot/gtest.sh test_state | tail -1` prints `GDTEST OK`."],
  oos=["`start_game` (src/sim/newgame.js: shop, auction, headline; that is a sim port)."]),

 dict(id="GDF09", title="Godot: CoreSave (port of save/save.js)", needs=["GDF01", "GDF02", "GDF15"],
  files=["godot/autoload/save.gd", "godot/tests/test_save.gd"],
  goal="Save and load a game state (and the settings) as JSON files under `user://`, with the same validity rules as `src/save/save.js`. It is a static helper class (`class_name CoreSave`), NOT an autoload.",
  read=["src/save/save.js (read it all)", "src/game.js (loadSettings, SETTINGS_KEY, DEFAULT_SETTINGS)", "tests/save.test.mjs", "godot/core/json.gd (GDF15)", HARNESS, JSON_NOTE],
  steps=[
   "`godot/autoload/save.gd`: `class_name CoreSave`, `extends RefCounted`, static, typed. Constants: `const SAVE_PATH := \"user://save.json\"`, `const SETTINGS_PATH := \"user://settings.json\"`, `const REQUIRED_KEYS: Array[String] = [\"day\", \"cash\", \"reputation\", \"buzz\", \"garageSlots\", \"cars\", \"shop\", \"requests\", \"auction\", \"stats\", \"plates\", \"flags\", \"rng\"]`.",
   "`serialize(state: Dictionary) -> String` (`CoreJson.stringify(state)`). `deserialize(text: String) -> Variant`: returns the state Dictionary or null; null when the text is not JSON, not an object, `v` is not 1 (compare numerically), any REQUIRED_KEY is missing, or `cars` is not an Array; extra keys are tolerated. Never errors.",
   "`save_to(state: Dictionary, path: String = SAVE_PATH) -> bool` (false when the file cannot be written). `load_from(path: String = SAVE_PATH) -> Variant` (null when the file is missing or invalid). `has_save(path: String = SAVE_PATH) -> bool` (`load_from(path) != null`). `clear_save(path: String = SAVE_PATH) -> bool`: true when the file is gone afterwards (also true when it never existed); use `DirAccess.remove_absolute(ProjectSettings.globalize_path(path))`.",
   "Settings (from src/game.js): `static func default_settings() -> Dictionary` returns `{\"crt\": false, \"sound\": true, \"music\": true}` (a new Dictionary each call). `load_settings(path: String = SETTINGS_PATH) -> Dictionary`: defaults when the file is missing, corrupt or not an object; otherwise `crt` is true only when the stored value is exactly `true`, and `sound` / `music` are false only when the stored value is exactly `false`. `save_settings(settings: Dictionary, path: String = SETTINGS_PATH) -> bool`.",
   "`godot/tests/test_save.gd`: a helper `func _good() -> Dictionary` building a minimal valid state by hand (`v: 1`, every REQUIRED_KEY present with simple values, `cars: []`, `rng: 5`, `cash: 20000`). Tests: `test_roundtrip_string` (deserialize(serialize(x)) is `GoldenUtil.same` to x); `test_rejects` (not-JSON text, `\"[1,2]\"`, `\"null\"`, a state with `v` 2, with `v` missing, with each required key removed in turn, with `cars` a Dictionary: all null); `test_extra_keys_ok`; `test_file_roundtrip` using the temp path `user://test_save_tmp.json`: `save_to` true, `has_save` true, `load_from` same as the state, `clear_save` true, `has_save` false, `clear_save` again true; `test_load_missing_is_null`; `test_save_to_bad_path` (`save_to(_good(), \"user://no_such_dir_xyz/s.json\")` is false); `test_settings` with temp path `user://test_settings_tmp.json`: missing file gives defaults; save `{crt: true, sound: false, music: true}` and load it back identical; a file containing `{\"crt\": 1, \"sound\": 0}` loads as `crt` false, `sound` true, `music` true; a file containing `garbage` loads defaults; clean up the temp file at the end of the test."],
  accept=["`sh tools/godot/gtest.sh test_save | tail -1` prints `GDTEST OK`."],
  oos=["Game.gd wiring (GDF10). Cloud saves."]),

 dict(id="GDF10", title="Godot: Game autoload shell", needs=["GDF08", "GDF09", "GDF15"],
  files=["godot/autoload/game.gd", "godot/tests/fake_actions.gd", "godot/tests/test_game.gd"],
  goal="The `Game` singleton: the port of `src/game.js` createGame. It owns `state`, starts / continues / erases games, saves after each successful action, and `act()` dispatches an action NAME to the sim ports (which other cards write). Scenes only read `Game.state` and call `Game.act`.",
  read=["src/game.js (read it all)", "src/sim/actions.js (result shape `{ok, msg}`; first 80 lines)", "src/sim/newgame.js", "godot/core/state.gd (GDF08)", "godot/autoload/save.gd (GDF09)", HARNESS],
  steps=[
   "`godot/autoload/game.gd` (replace the stub): `extends Node`. Signals: `signal changed`, `signal toast_requested(text: String)`, `signal day_advanced`, `signal game_over`. Vars: `var state: Dictionary = {}`, `var settings: Dictionary = CoreSave.default_settings()`, `var save_path: String = CoreSave.SAVE_PATH`, `var settings_path: String = CoreSave.SETTINGS_PATH`.",
   "Action table: `var _actions: Dictionary` initialised from this constant (entry = `[script path, function name, [param keys in call order]]`): `\"buy_car\": [\"res://sim/actions.gd\", \"buy_car\", [\"listing_id\"]]`, `\"rent_car\"` (same, `listing_id`), `\"return_rental\"` (`car_id`), `\"sell_to_dealer\"` (`car_id`), `\"buy_slot\"` (no params), `\"wait_day\"` (no params), `\"service_car\": [\"res://sim/garage.gd\", \"service_car\", [\"car_id\", \"kind\"]]`, `\"fix_fault\"` (garage.gd, `car_id`), `\"restore_car\"` (garage.gd, `car_id`), `\"accept_job\": [\"res://sim/jobresolve.gd\", \"accept_job\", [\"request_id\", \"car_id\"]]`, `\"advertise\": [\"res://sim/adsim.gd\", \"advertise\", [\"media_id\"]]`. `func register_action(action: String, script_path: String, func_name: String, param_keys: Array) -> void` adds or replaces an entry (later cards add the auction actions this way); `func has_action(action: String) -> bool`.",
   "`func act(action: String, params: Dictionary = {}) -> Dictionary`, in this order: (a) `state.is_empty()` -> return `{\"ok\": false, \"msg\": \"No game running\"}`; (b) unknown name -> `{\"ok\": false, \"msg\": \"Unknown action: \" + action}`; (c) script path not found (`ResourceLoader.exists`) -> `{\"ok\": false, \"msg\": \"Action not built yet: \" + action}`; (d) a param key missing from `params` -> `{\"ok\": false, \"msg\": \"Missing parameter: \" + key}`; (e) `var r: Variant = load(path).callv(func_name, [state] + args)` (the sim functions are `static`, take the state Dictionary first and return a Dictionary); (f) when `r` is a Dictionary with `ok == true`: `save_now()`, then emit `day_advanced`, then `changed`, then play the cash sound if the Sfx singleton exists (`Engine.get_main_loop().root.get_node_or_null(\"Sfx\")` and it `has_method(\"play\")`), then if `state.flags.gameOver == true` emit `game_over`; when `ok == false` and it has a non-empty `msg` emit `toast_requested(msg)` (no other signal); (g) return `r` untouched (a result without an `ok` field passes through with no signals).",
   "Other methods: `func new_game(seed_value: int = -1) -> void`: seed = `seed_value` unless it is -1, then `int(Time.get_unix_time_from_system()) + 1`; `state = ` the result of `load(\"res://sim/newgame.gd\").start_game(seed)` when that file exists (`ResourceLoader.exists`), else `CoreState.new_game_state(seed)`; `save_now()`; emit `changed`. `func continue_game() -> bool`: load with `CoreSave.load_from(save_path)`; when null emit `toast_requested(\"No saved game\")` and return false; else set `state`, emit `changed`, return true. `func has_save() -> bool`, `func erase_save() -> bool` (via CoreSave with `save_path`), `func save_now() -> bool` (`CoreSave.save_to(state, save_path)`), `func load_settings() -> void` (`settings = CoreSave.load_settings(settings_path)`), `func save_settings() -> bool`. `func _ready() -> void: load_settings()`.",
   "`godot/tests/fake_actions.gd` (test helper, no tests in it): `extends RefCounted`; `static func double_cash(state: Dictionary, n: int) -> Dictionary` (`state.cash = state.cash * n`, returns `{\"ok\": true, \"msg\": \"doubled\"}`); `static func refuse(_state: Dictionary) -> Dictionary` (returns `{\"ok\": false, \"msg\": \"No way\"}`); `static func end_it(state: Dictionary) -> Dictionary` (sets `state.flags.gameOver = true`, returns ok true); `static func plain(_state: Dictionary) -> int` (returns 5).",
   "`godot/tests/test_game.gd`: create the Game under test with `var g: Node = load(\"res://autoload/game.gd\").new()` (NOT the autoload; it is not in the tree), set `g.save_path = \"user://test_game_save.json\"` and `g.settings_path = \"user://test_game_settings.json\"`, register the four fake actions (`double_cash` with `[\"n\"]`, `refuse`, `end_it`, `plain` with no params; script path `res://tests/fake_actions.gd`), and `g.free()` plus delete the two temp files at the end of each test. Count signals with lambdas over a shared Array, e.g. `var hits := [0]; g.changed.connect(func(): hits[0] += 1)`. Tests: `test_no_game` (act before new_game gives `No game running`); `test_new_game` (`new_game(7)`: `state.seed == 7`, `state.day == 1`, `state.cash == 20000`, `g.has_save()` true); `test_unknown_action` (`msg` is `Unknown action: nope`, `ok` false); `test_missing_param` (`act(\"double_cash\", {})` -> `Missing parameter: n`); `test_success` (`act(\"double_cash\", {\"n\": 2})` returns ok true, `state.cash == 40000`, `changed` once, `day_advanced` once, `toast_requested` zero times, and a fresh `continue_game()` after resetting `g.state = {}` restores cash 40000); `test_refused` (ok false; `toast_requested` got text `No way`; `day_advanced` and `changed` zero); `test_game_over_signal` (`end_it` emits `game_over` once); `test_passthrough` (`plain` returns 5 and no signals); `test_not_built_yet` (`act(\"buy_car\", {\"listing_id\": 1})` gives ok false with `msg` either `Action not built yet: buy_car` or any msg when the sim file already exists; just check `ok` is false OR the call returned a Dictionary); `test_has_action` (`buy_car`, `accept_job`, `advertise` true; `nope` false); `test_continue_without_save` (returns false and emits the toast `No saved game`); `test_settings_roundtrip`."],
  accept=["`sh tools/godot/gtest.sh test_game | tail -1` prints `GDTEST OK`.",
          "`sh tools/godot/gtest.sh | tail -1` prints `GDTEST OK` (the whole suite)."],
  oos=["The sim ports themselves (GDS cards). Scenes. Scene stack / navigation (GDR cards). Music."]),

 dict(id="GDF11", title="Godot: make gtest and hello scene screenshot check", needs=["GDF01", "GDF02"],
  files=["Makefile", "godot/scenes/hello.tscn", "godot/scenes/hello.gd", "godot/tests/test_hello.gd", "godot/project.godot"],
  goal="Wire `make gtest`, and prove the screenshot path works end to end with a tiny scene (title text on the night-blue background) so every later scene card has a working example of a scene, a smoke test and a `gshot.sh` screenshot.",
  read=[PLAN + " section 'Card rules for Godot cards'", "Makefile (it already has `test`, `serve`... targets; if it does not exist in your checkout create it with only the gtest target)", "tools/godot/gshot.sh and tools/godot/shot.gd", HARNESS],
  steps=[
   "`Makefile`: add `gtest` to the `.PHONY:` list (create the line if missing) and add a target `gtest:` whose single recipe line (a TAB, then) is `sh tools/godot/gtest.sh`. Do not change other targets.",
   "`godot/scenes/hello.gd`: `extends Control`, `func get_title() -> String: return $Title.text`.",
   "`godot/scenes/hello.tscn` (Godot 4 text scene, `[gd_scene load_steps=2 format=3]`, one ext_resource for hello.gd): root node `Hello` of type `Control` with the script, anchors preset full rect (`layout_mode = 3`, `anchors_preset = 15`, `anchor_right = 1.0`, `anchor_bottom = 1.0`, `grow_horizontal = 2`, `grow_vertical = 2`); child `Background` (`ColorRect`, full rect likewise, `color = Color(0.105882, 0.0901961, 0.207843, 1)` which is #1B1735); child `Title` (`Label`, full rect, `text = \"Webb, where's my car?\"`, `horizontal_alignment = 1`, `vertical_alignment = 1`, theme font size override 48 via `theme_override_font_sizes/font_size = 48`, `theme_override_colors/font_color = Color(0.94902, 0.85098, 0.541176, 1)` which is #F2D98A).",
   "In `godot/project.godot` add under `[application]` the line `run/main_scene=\"res://scenes/hello.tscn\"` (GDR cards replace it later).",
   "`godot/tests/test_hello.gd`: `test_scene_loads`: `var packed: PackedScene = load(\"res://scenes/hello.tscn\")`, `var s := packed.instantiate()`, check `s is Control`, `s.get_node(\"Title\") is Label`, `s.get_node(\"Background\") is ColorRect`, `s.get_title() == \"Webb, where's my car?\"`, then `s.free()`. `test_ascii_title`: the title contains no character above code 127.",
   "Run the screenshot command from the acceptance list, then LOOK at `/tmp/hello.png` with the Read tool and say in your summary what it shows (expected: a dark blue 1280x720 picture with pale-gold centred text)."],
  accept=["`make -n gtest` prints `sh tools/godot/gtest.sh`.",
          "`sh tools/godot/gshot.sh scenes/hello.tscn /tmp/hello.png 8` prints `wrote /tmp/hello.png`, and `file /tmp/hello.png` mentions `1280 x 720`.",
          "`sh tools/godot/gtest.sh test_hello | tail -1` prints `GDTEST OK`."],
  oos=["Real scenes, theme, fonts. Other Makefile targets (the JS `test` target stays as is)."]),

 dict(id="GDF12", title="Godot: Sfx autoload (procedural sounds)", needs=["GDF01", "GDF02"],
  files=["godot/autoload/sfx.gd", "godot/tests/test_sfx.gd"],
  goal="The `Sfx` singleton: the same nine sounds as `src/audio/sfx.js` (names click, cash, fail, fanfare, ring, tada, crash, paper, bid), synthesised in code into `AudioStreamWAV` buffers. No audio files.",
  read=["src/audio/sfx.js (read it all: the SOUNDS table is the spec)", "tests/sfx.test.mjs", HARNESS],
  steps=[
   "`godot/autoload/sfx.gd` (replace the stub): `extends Node`. `const RATE := 22050`. `var muted: bool = false`, `var music_ducked: bool = false`, `var _player: AudioStreamPlayer`, `var _streams: Dictionary = {}` (cache). `const SOUNDS: Dictionary` with the exact JS events, each event a Dictionary `{\"type\": \"square\"|\"triangle\"|\"noise\", \"freq\": float, \"end_freq\": float, \"start\": float, \"dur\": float, \"vol\": float}` (`end_freq` equals `freq` except for noise). Values: click: square 880, start 0, dur 0.04, vol 0.2. cash: square 1200 (0, 0.06, 0.2) and square 1800 (0.06, 0.06, 0.2). fail: triangle 330 (0, 0.12, 0.3), 262 (0.12, 0.12, 0.3), 196 (0.24, 0.12, 0.3). fanfare: square at 262, 330, 392, 523, 659 starting at 0, 0.1, 0.2, 0.3, 0.4, each dur 0.1 vol 0.2. ring: four bursts starting 0, 0.25, 0.5, 0.75; each burst = square 400 and square 450 at that start, dur 0.15, vol 0.2 (8 events). tada: triangle 392, 494, 587 all at start 0, dur 0.4, vol 0.2. crash: noise freq 2400 end_freq 200, start 0, dur 0.3, vol 0.4. paper: noise freq 3000 end 3000, dur 0.12, vol 0.25. bid: triangle 660, dur 0.08, vol 0.25.",
   "`func sound_names() -> Array`: the keys of SOUNDS. `func duration_of(sound: String) -> float`: the largest `start + dur` of its events (0.0 when unknown).",
   "`func build_stream(sound: String) -> AudioStreamWAV` (null when the name is unknown): `n = int(ceil(duration_of(sound) * RATE))` samples as a `PackedFloat32Array` of zeros; for each event add `vol * wave * envelope` into samples `[int(start * RATE), int((start + dur) * RATE))`. Per sample: time `u = (i - first) / RATE`; frequency `f = freq + (end_freq - freq) * (u / dur)` (linear glide) accumulated as `phase += TAU * f / RATE`. Waves: square = `1.0 if sin(phase) >= 0.0 else -1.0`; triangle = `asin(sin(phase)) * 2.0 / PI`; noise = a deterministic white noise `w` from the generator `seed = (seed * 1664525 + 1013904223) & 0xFFFFFFFF` (seed starts at 12345 per event, `w = seed / 2147483648.0 - 1.0`) passed through a one-pole lowpass `y += a * (w - y)` with `a = clampf(TAU * f / RATE, 0.0, 1.0)`. Envelope (seconds): `attack = minf(0.01, dur / 4.0)`, `release = minf(0.03, dur / 4.0)`; gain rises linearly 0 to 1 over the attack, stays 1, falls linearly to 0 over the last `release` seconds. Convert to 16-bit little endian PCM (`clampf(sample, -1.0, 1.0) * 32767.0` as int, written with `PackedByteArray.encode_s16`), then `var w := AudioStreamWAV.new()`, `w.format = AudioStreamWAV.FORMAT_16_BITS`, `w.mix_rate = RATE`, `w.stereo = false`, `w.data = bytes`; return it. Cache by name in `_streams`.",
   "`func play(sound: String) -> bool`: false when `muted`, when the name is unknown, or when the node is not inside the scene tree; else create `_player` on first use (`AudioStreamPlayer`, `add_child`), set `_player.stream = build_stream(sound)`, `_player.play()`, return true. `func set_muted(on: bool) -> void`, `func set_music_duck(on: bool) -> void` (just stores the flag, like the JS), `func unlock() -> void` (empty; kept so call sites match the JS).",
   "`godot/tests/test_sfx.gd`: `var s: Node = load(\"res://autoload/sfx.gd\").new()` (free it at the end). `test_names`: `sound_names()` sorted equals `[\"bid\", \"cash\", \"click\", \"crash\", \"fail\", \"fanfare\", \"paper\", \"ring\", \"tada\"]`. `test_durations`: `duration_of` near 0.04 (click), 0.12 (cash), 0.36 (fail), 0.5 (fanfare), 0.9 (ring), 0.4 (tada), 0.3 (crash), 0.12 (paper), 0.08 (bid), eps 1e-9; unknown is 0. `test_streams`: for every name `build_stream` is not null, `format == FORMAT_16_BITS`, `mix_rate == 22050`, `data.size() == 2 * int(ceil(duration_of(n) * 22050.0))`, and the data is not all zeros; peak absolute sample for `click` is at most `0.2 * 32767 + 1` and at least 3000; `build_stream(\"nope\")` is null. `test_deterministic`: two builds of `crash` have identical `data`. `test_mute`: `play(\"click\")` is false when `muted` is true, false for an unknown name, and false while the node is outside the tree."],
  accept=["`sh tools/godot/gtest.sh test_sfx | tail -1` prints `GDTEST OK`."],
  oos=["Music. Mixing buses. Sound files."]),

 dict(id="GDF13", title="Godot: UiTokens (port of ui/tokens.js)", needs=["GDF04"],
  files=["godot/ui/tokens.gd", "tools/godot/golden_tokens.mjs", "godot/tests/golden/tokens.json", "godot/tests/test_tokens.gd"],
  goal="The design tokens in one GDScript class: palette (theme.js PALETTE plus tokens.js COLOR), spacing grid, screen zones, type scale, motion timings and easing curves, compared to the JS values by a golden fixture.",
  read=["src/ui/tokens.js (read it all)", "src/ui/theme.js (PALETTE only, lines 1-30)", "tests/tokens.test.mjs", HARNESS, GOLD, JSCN],
  steps=[
   "`godot/ui/tokens.gd`: `class_name UiTokens`, `extends RefCounted`, static, typed. Colours are stored as hex STRINGS exactly as in the JS (upper-case digits as written there): `const PALETTE: Dictionary` (all 23 keys of theme.js PALETTE) and `const COLOR: Dictionary` (all 29 keys of tokens.js COLOR, camelCase key names kept, e.g. `woodLight`, `bannerTop`). `static func col(key: String) -> Color`: `Color(COLOR[key])` when the key is in COLOR, else `Color(PALETTE[key])` when in PALETTE, else `Color.MAGENTA` (and `push_error`). `const FONT_TITLE := \"res://art/fonts/PressStart2P-Regular.ttf\"` and `const FONT_BODY := \"res://art/fonts/VT323-Regular.ttf\"` (the art cards copy the fonts there).",
   "`const SPACE: Dictionary = {1: 4, 2: 8, 3: 12, 4: 16, 5: 24, 6: 32, 7: 48}`; `static func sp(n: int) -> int` (the value; for any n outside 1..7 `push_error(\"bad space\")` and return 0). `const ZONES: Dictionary` with `banner {x:0,y:0,w:1280,h:120}`, `tableau {x:0,y:120,w:1280,h:470}`, `hud {x:0,y:590,w:1280,h:130}`. `const FLOOR: Dictionary = {\"title\": 16, \"body\": 22}`. `const TYPE: Dictionary` with the nine roles of the JS (`logo`, `h1`, `h2`, `h3`, `button`, `bannerText` (has `lineH`: 28), `hero`, `body`, `caption`), each `{\"kind\": ..., \"px\": ...}`. `static func font_path(role: String) -> String` (FONT_TITLE for kind `title`, FONT_BODY for `body`; `\"\"` for an unknown role). `const MOTION: Dictionary` with all 16 timings of the JS.",
   "Easing: `static func clamp01(u: float) -> float`, `static func lerp_to(a: float, b: float, u: float) -> float` (`a + (b - a) * u`, not clamped). `const EASE_NAMES: Array[String] = [\"linear\", \"outQuad\", \"outCubic\", \"inOutQuad\", \"outBack\", \"outBounce\"]`. `static func ease_named(curve: String, u: float) -> float`: clamp `u` with `clamp01` then apply the curve with the JS formulas: linear `u`; outQuad `1 - (1-u)*(1-u)`; outCubic `1 - pow(1-u, 3)`; inOutQuad `2*u*u` for u < 0.5 else `1 - pow(-2*u + 2, 2) / 2`; outBack with `C1 = 1.70158`, `C3 = C1 + 1`: `1 + C3*pow(u-1, 3) + C1*pow(u-1, 2)`; outBounce with `N1 = 7.5625`, `D1 = 2.75` and the four-branch formula of the JS (read EASE.outBounce). Unknown curve: `push_error(\"bad ease\")` and return `u`. (Do not name anything `ease`: that is a GDScript built-in.)",
   "`tools/godot/golden_tokens.mjs`: emit `{ PALETTE, COLOR, SPACE, ZONES, FLOOR, TYPE, MOTION, eases: { <name>: [[u, ease(name, u)] for u in [-0.5, 0, 0.1, 0.25, 0.5, 0.75, 0.9, 1, 1.5]] for each name in Object.keys(EASE) }, lerp: [[0,10,0.5,5],[2,4,0.25,2.5],[10,0,1.5,-5]] (a, b, u, lerp(a,b,u) computed by the JS), clamp01: [[-1,0],[0.3,0.3],[2,1]] }` (import `PALETTE` from `../../src/ui/theme.js`, the rest from `../../src/ui/tokens.js`).",
   "`godot/tests/test_tokens.gd`: `test_palette_matches_js` (`GoldenUtil.same(UiTokens.PALETTE, fx.PALETTE)`, same for COLOR; COLOR has 29 keys, PALETTE 23; every value matches `^#[0-9A-Fa-f]{6}$` via `RegEx`), `test_col` (`UiTokens.col(\"ink\")` equals `Color(\"#14102A\")`; `col(\"gold\")` equals `Color(\"#E8B923\")`), `test_space` (for n 1..7 `sp(n) == fx.SPACE[str(n)]`), `test_zones_type_motion_floor` (GoldenUtil.same for ZONES, FLOOR, TYPE, MOTION), `test_zones_stack` (banner bottom 120 equals tableau y, tableau bottom 590 equals hud y, hud bottom 720), `test_eases` (every sample within 1e-9), `test_lerp_clamp`, `test_font_path` (`font_path(\"h1\") == UiTokens.FONT_TITLE`, `font_path(\"body\") == UiTokens.FONT_BODY`, `font_path(\"zzz\") == \"\"`), `test_ascii_source` (godot/ui/tokens.gd has no byte >= 128)."],
  accept=["`sh tools/godot/golden.sh tokens` prints `wrote godot/tests/golden/tokens.json`.",
          "`sh tools/godot/gtest.sh test_tokens | tail -1` prints `GDTEST OK`."],
  oos=["theme.tres, widgets, shaders (GDU cards). `shade`/`rgba` helpers (Godot has Color.lightened/darkened)."]),

 dict(id="GDF14", title="Godot: API reference docs/GODOT_API.md", needs=["GDF03", "GDF04", "GDF05", "GDF06", "GDF07", "GDF08", "GDF09", "GDF10", "GDF11", "GDF12", "GDF13"],
  files=["docs/GODOT_API.md"],
  goal="A single reference, written from the code AS BUILT, that the other Godot cards (sim ports, UI, rooms, art) read first. Short, exact, ASCII.",
  read=[PLAN, "godot/core/*.gd, godot/autoload/*.gd, godot/ui/tokens.gd, godot/tests/harness.gd, godot/tests/golden_util.gd, godot/tests/runner.gd", "tools/godot/*.sh, tools/godot/*.mjs", "godot/project.godot", "Run `grep -n -E '^(static )?func |^signal |^const |^var |^class_name ' <file>` on each file to get the exact public signatures"],
  steps=[
   "Write `docs/GODOT_API.md` (plain ASCII markdown, 120 to 260 lines). One level-2 heading per item, spelled exactly: `## Project layout`, `## CoreJson`, `## CoreRng`, `## CoreClock`, `## CoreFormat`, `## CoreState`, `## CoreSave`, `## Game`, `## Data`, `## Sfx`, `## UiTokens`, `## Tests`, `## Golden fixtures`, `## Conventions`.",
   "For each class/autoload heading: file path, `class_name` (or autoload name), then a bullet list with ONE LINE per public function, signal or constant exactly as declared in the code (copy the signature line; add a few words on behaviour only where the JS differs, e.g. out-of-range sentinels, hi/lo inclusive). Do not invent anything: every name in the doc must exist in the code (check with grep).",
   "`## Project layout`: the folder list (`autoload/ core/ sim/ data/ scenes/ tv/ ui/ art/ tests/`) with one line each and where the autoloads are registered (project.godot). `## Tests`: how to run all tests and one (`sh tools/godot/gtest.sh`, `sh tools/godot/gtest.sh test_rng`, `make gtest`), the harness helpers, the rule that a test file is `godot/tests/test_<name>.gd` extending `res://tests/harness.gd`, that `autoload(name)` gives the singleton and fixtures are loaded with `GoldenUtil`, and how scenes are checked (`sh tools/godot/gshot.sh scenes/hello.tscn /tmp/x.png`). `## Golden fixtures`: the 4-step pattern (write `tools/godot/golden_<name>.mjs` using `emit`, run `sh tools/godot/golden.sh <name>`, load with `GoldenUtil.fixture`, compare with `GoldenUtil.diff`).",
   "`## Conventions` must contain these rules as short bullets: sim ports are `Sim` + PascalCase of the JS file name in `godot/sim/<file>.gd` (e.g. `SimJobResolve`), static functions taking the state Dictionary first, function names are the JS names in snake_case, state keys keep the JS camelCase; every action returns `{ok: bool, msg: String}`; whole JSON numbers are ints, GDScript `/` on ints truncates (convert with `float()`); no `randf`/`randi`/`Time` in sim code, only `CoreRng`; player text ASCII only, pound sign only via `CoreFormat.money()`, stars via `CoreFormat.stars()`; scenes read `Game.state` and call `Game.act(name, params)` only; the JS functions inside data modules (chatterFor, ownerName, customerName, fillText, modelOf, ...) are ported by sim cards, `Data` only serves tables; where the JS threw an error the GDScript returns a sentinel (empty Dictionary, -1, empty String, null)."],
  accept=["`for n in CoreJson CoreRng CoreClock CoreFormat CoreState CoreSave Game Data Sfx UiTokens Tests Conventions; do grep -q \"^## $n\" docs/GODOT_API.md || echo MISSING $n; done` prints nothing.",
          "`grep -nP '[^\\x00-\\x7F]' docs/GODOT_API.md` prints nothing, and `wc -l docs/GODOT_API.md` is between 120 and 260.",
          "For every function name you documented under CoreRng, e.g. `grep -c 'static func rand_int' godot/core/rng.gd` is 1 (spot check three names per class and paste the output)."],
  oos=["Any code change. Describing classes that other planners add later (sim ports, TV, rooms): they add their own sections."]),
]
